<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
$s=preg_replace('/[^a-z0-9-]/','',strtolower((string)($_GET['tool']??'')))?:'tool';
$n=['timestamp-converter'=>'Timestamp Converter','unix-timestamp'=>'Unix Timestamp','stopwatch-timer'=>'Stopwatch / Timer'];
$t=$n[$s]??'SmartToolz Tool';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($t)?> — SmartToolz</title><style>body{margin:0;background:#f6f8fc;color:#172033;font-family:system-ui,Arial}.x{max-width:900px;margin:40px auto;padding:28px}.card{background:#fff;border:1px solid #e5e9f0;border-radius:22px;padding:30px;box-shadow:0 15px 45px #1d274010}h1{font-size:42px;margin:8px 0}p{color:#707b8e}input{width:100%;padding:13px;border:1px solid #dfe4ec;border-radius:11px;box-sizing:border-box;margin:8px 0 15px}.btn{padding:12px 18px;border:0;border-radius:11px;background:#635bff;color:#fff;font-weight:800;cursor:pointer}.out{margin-top:15px;padding:15px;border-radius:12px;background:#f7f8fb;border:1px solid #e5e9f0;font-size:20px}</style></head><body><?php require_once __DIR__.'/header.php'; ?><main class="x"><div class="card"><small style="color:#635bff;font-weight:800">SMARTTOOLZ TOOL</small><h1><?=htmlspecialchars($t)?></h1><?php if($s==='timestamp-converter'): ?><p>Convert a Unix timestamp into a readable date.</p><input id="v" type="number" placeholder="Unix timestamp"><button class="btn" id="run">Convert</button><?php elseif($s==='unix-timestamp'): ?><p>Get the current Unix timestamp.</p><button class="btn" id="run">Get Timestamp</button><?php else: ?><p>Use a simple online stopwatch.</p><div class="out" id="out">00:00:00.000</div><button class="btn" id="start">Start</button> <button class="btn" id="stop">Stop</button> <button class="btn" id="reset">Reset</button><?php endif; ?><div class="out" id="out2"></div></div></main><?php require_once __DIR__.'/footer.php'; ?><script>(function(){var s=<?=json_encode($s)?>,out=document.getElementById('out'),o2=document.getElementById('out2'),timer=null,start=0,elapsed=0;if(s==='timestamp-converter'){document.getElementById('run').onclick=function(){var v=Number(document.getElementById('v').value);o2.textContent=Number.isFinite(v)?new Date(v*1000).toString():'Enter a valid timestamp'}}else if(s==='unix-timestamp'){document.getElementById('run').onclick=function(){o2.textContent=Math.floor(Date.now()/1000)}}else{function draw(){var z=elapsed+(timer?Date.now()-start:0),h=String(Math.floor(z/3600000)).padStart(2,'0'),m=String(Math.floor(z/60000)%60).padStart(2,'0'),q=String(Math.floor(z/1000)%60).padStart(2,'0'),ms=String(z%1000).padStart(3,'0');out.textContent=h+':'+m+':'+q+'.'+ms}document.getElementById('start').onclick=function(){if(!timer){start=Date.now();timer=setInterval(draw,30)}};document.getElementById('stop').onclick=function(){if(timer){elapsed+=Date.now()-start;clearInterval(timer);timer=null;draw()}};document.getElementById('reset').onclick=function(){if(timer){clearInterval(timer);timer=null}elapsed=0;draw()}}})();</script></body></html>